<?php
declare(strict_types=1);namespace App\Http\Controllers\Hrd;use App\Http\Controllers\Controller;use App\Models\{Personnel,PersonnelAttendance,PersonnelAttendanceLateRemark,PersonnelCashAdvance,PersonnelLeaveRequest,PersonnelPayroll};use Illuminate\View\View;
class HrdDashboardController extends Controller{public function __invoke():View{$today=today();$active=Personnel::where('is_active',true)->count();$attendance=PersonnelAttendance::whereDate('attendance_date',$today);$period=PersonnelPayroll::where('period_start','<=',$today)->where('period_end','>=',$today);return view('hrd.dashboard',['title'=>'Dashboard HRD','stats'=>['total'=>Personnel::count(),'active'=>$active,'teachers'=>Personnel::where('is_active',true)->where('position','like','%guru%')->count(),'staff'=>Personnel::where('is_active',true)->where('position','not like','%guru%')->count(),'checked_in'=>(clone $attendance)->whereNotNull('check_in_time')->count(),'checked_out'=>(clone $attendance)->whereNotNull('check_out_time')->count(),'late'=>(clone $attendance)->where('status','terlambat')->count(),'leave'=>(clone $attendance)->whereIn('status',['izin','sakit','cuti'])->count(),'missing'=>max(0,$active-(clone $attendance)->distinct('personnel_id')->count('personnel_id')),'pending_leave'=>PersonnelLeaveRequest::where('status','pending')->count(),'pending_advance'=>PersonnelCashAdvance::where('status','pending')->count(),'pending_late'=>PersonnelAttendanceLateRemark::where('status','pending')->count(),'payroll_count'=>(clone $period)->count(),'payroll_total'=>(clone $period)->sum('total'),'active_advance'=>PersonnelCashAdvance::whereIn('status',['disbursed','partially_paid'])->count()],'attendances'=>(clone $attendance)->with('personnel')->latest('check_in_time')->limit(5)->get(),'leaves'=>PersonnelLeaveRequest::with('personnel')->latest()->limit(5)->get(),'payrolls'=>PersonnelPayroll::with('personnel')->latest()->limit(5)->get()]);}}
